<?php

namespace App\Http\Middleware;

use Closure;
use Illuminate\Http\Request;
use Symfony\Component\HttpFoundation\Response;

/**
 * Holds an account on the change-password page until its emailed temporary
 * password has been replaced.
 *
 * Without this the flag would be decoration — the temporary password, which
 * travelled through email in plain text and was generated by someone else,
 * would stay valid indefinitely.
 */
class ForcePasswordChange
{
    /**
     * Routes reachable while the change is outstanding: the change form itself,
     * its POST, and logout. Anything else redirects back to the form.
     */
    private const ALLOWED = [
        'account.password',
        'account.password.update',
        'logout',
    ];

    public function handle(Request $request, Closure $next): Response
    {
        $user = $request->user();

        if ($user && $user->must_change_password && ! $request->routeIs(self::ALLOWED)) {
            return redirect()->route('account.password')
                ->with('status', 'Please set your own password before continuing.');
        }

        return $next($request);
    }
}
